{
  "status": "SUPPORTED",
  "task_summary": "Identify compatible components, fasten them to a workpiece, and place the tool on the workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "target_part",
        "entity_kind": "OBJECT",
        "function": "The workpiece located at the marked workbench location that requires fastening.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["assembly", "part", "device"],
        "required_properties": []
      },
      {
        "id": "compatible_component",
        "entity_kind": "OBJECT",
        "function": "The physical component(s) needed to secure the target_part.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screw", "bolt", "clip", "pin", "nut"],
        "required_properties": []
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "The implement used to apply the fastening.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screwdriver", "tool", "clamp"],
        "required_properties": []
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "The surface where the tool must be left after the task.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "desk"],
        "required_properties": []
      }
    ],
    "functional_relations": [
      {
        "id": "relation_1",
        "relation": "fits_into",
        "participant_roles": ["target_part", "compatible_component"],
        "required": true
      },
      {
        "id": "relation_2",
        "relation": "operates_on",
        "participant_roles": ["target_part", "compatible_component", "fastening_tool"],
        "required": true
      },
      {
        "id": "relation_3",
        "relation": "rests_on",
        "participant_roles": ["fastening_tool", "workbench"],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "operation_1",
        "operation": "apply_fastener",
        "participant_roles": ["target_part", "compatible_component", "fastening_tool"],
        "operation_count": 1
      },
      {
        "id": "operation_2",
        "operation": "place_object",
        "participant_roles": ["fastening_tool", "workbench"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "target_part": [
        {
          "label": "black_assembly_with_yellow_blue_parts",
          "visual_description": "A black rectangular tray-like object with yellow and blue components sitting on the table surface."
        }
      ],
      "compatible_component": [],
      "fastening_tool": [],
      "workbench": [
        {
          "label": "wooden_table",
          "visual_description": "A wooden workbench with drawers underneath and a cabinet behind it."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "drawers",
        "label": "closed_drawers_under_table",
        "visual_description": "Two blue drawers located beneath the table surface.",
        "reason": "Closed storage structure likely containing components or tools."
      },
      {
        "id": "cabinet",
        "label": "closed_cabinet_behind_table",
        "visual_description": "A tall blue cabinet standing against the wall behind the table.",
        "reason": "Closed storage structure likely containing components or tools."
      }
    ],
    "inspection_order": ["drawers", "cabinet"]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
